package test;

import org.eclipse.jface.text.Position;
import org.eclipse.jface.text.source.ISourceViewer;
import org.eclipse.swt.custom.StyledText;

// Some other class not inheriting from AbstractInlinedAnnotation
class OtherAnnotation {
    public OtherAnnotation(Position pos, StyledText styledText) {
        // Does something else
    }
}

public class MyClass {
    public void test(Position pos, ISourceViewer viewer) {
        // This should not be matched, as OtherAnnotation is not a subtype of AbstractInlinedAnnotation
        OtherAnnotation annotation = new OtherAnnotation(pos, viewer.getTextWidget());

        // This should not be matched, as the second argument is not viewer.getTextWidget() literally
        StyledText anotherWidget = viewer.getTextWidget();
        OtherAnnotation anotherAnnotation = new OtherAnnotation(pos, anotherWidget);

        // This should not be matched, as the type is not a subclass of AbstractInlinedAnnotation
        new java.awt.Point(10, 20);
    }
}
